using UnityEngine;
using UnityEngine.InputSystem;

/// <summary>
/// Dit script regelt de beweging van de speler, inclusief acceleratie, remmen, sturen, driften en springen.
/// Volledig gebaseerd op physics, met een focus op een arcade-achtige rijervaring.
/// </summary>
public class Movement : MonoBehaviour
{
    [Header("Movement")]
    [SerializeField] private float speed = 20f;
    [SerializeField] private float maxSpeed = 20f;
    [SerializeField] private float jumpForce = 5f;
    [SerializeField] private float throttleResponse = 5f;

    [Header("Steering")]
    [SerializeField] private float turnSpeed = 120f;

    [Header("Drift")]
    [SerializeField] private float driftFactor = 0.98f;
    [SerializeField] private float extraDriftFactor = 0.995f;
    [SerializeField] private float velocityRotateSpeed = 2f;
    [SerializeField] private float extraDriftVelocityRotateSpeed = 0.5f;

    [SerializeField] private float bounceDriftFactor = 0.996f;

    [Header("Ground Check")]
    [SerializeField] private Grounded grounded;

    [Header("StopMovements")]
    [SerializeField] private BounceFeatures stopMovement_Bounce;

    [Header("Effects")]
    [SerializeField] private Transform JumpEffectPoint;

    private Rigidbody rb3D;
    private PlayerSFX playerSFX;
    private PlayerEffects playerVFX;

    private float driveInput;
    private float steer;
    private float smoothedThrottle;
    private bool isExtraDrifting;

    private void Awake()
    {
        rb3D = GetComponent<Rigidbody>();
        playerSFX = GetComponent<PlayerSFX>();
        playerVFX = GetComponent<PlayerEffects>();
    }

    // Vangt de input op voor gas geven (1) en achteruitrijden/remmen (-1)
    public void OnDrive(InputAction.CallbackContext context)
    {
        driveInput = Mathf.Clamp(context.ReadValue<float>(), -1f, 1f);
    }

    // Vangt de input op voor sturen (links = -1, rechts = 1)
    public void OnSteer(InputAction.CallbackContext context)
    {
        steer = context.ReadValue<float>();
    }

    // vangst input van drift knop
    public void OnDrift(InputAction.CallbackContext context)
    {
        if (context.performed)
        {
            isExtraDrifting = true;
        }
        else if (context.canceled)
        {
            isExtraDrifting = false;
        }
    }

    // FixedUpdate 
    private void FixedUpdate()
    {
        // Zorgt voor het geleidelijk optrekken en afremmen van de input (geen instant 0 naar 100)
        smoothedThrottle = Mathf.Lerp(
            smoothedThrottle,
            driveInput,
            throttleResponse * Time.fixedDeltaTime
        );

        HandleMovement();
        HandleSteering();
        ApplyDrift();
    }

    // MOVEMENT (Vooruit/achteruit)
    private void HandleMovement()
    {
        // Stop de code direct als de auto in de lucht hangt of net ergens tegenaan is geBOBed :)
        if (!grounded.isGrounded) return;

        float currentThrottle = smoothedThrottle;

        // Berekent hoe snel de auto momenteel vooruit (of achteruit) rijdt
        float forwardSpeed = Vector3.Dot(rb3D.linearVelocity, transform.forward);

        // Kracht toepassen op basis van de gas-input
        if (Mathf.Abs(currentThrottle) > 0.01f)
        {
            // Snelheidslimiet controleren voor achteruitrijden
            if (currentThrottle < 0f && forwardSpeed <= -maxSpeed * 0.5f)
            {
                return;
            }
            else
            {
                // Achteruitrijden gaat langzamer dan vooruitrijden
                float reverseMultiplier = (currentThrottle < 0f) ? 0.3f : 1.0f;
                rb3D.AddForce(transform.forward * currentThrottle * speed * reverseMultiplier, ForceMode.Acceleration);
            }
        }

        if (stopMovement_Bounce != null && !stopMovement_Bounce.hasCollided)
        {
            Vector3 localVelocity = transform.InverseTransformDirection(rb3D.linearVelocity);
            localVelocity.z = Mathf.Clamp(localVelocity.z, -maxSpeed * 0.5f, maxSpeed * 0.5f);
            rb3D.linearVelocity = transform.TransformDirection(localVelocity);
        }
    }

    // STUREN
    private void HandleSteering()
    {
        // Berekent hoe snel de auto rijdt t.o.v. de topsnelheid (sturen werkt alleen als je rijdt)
        float speedFactor = rb3D.linearVelocity.magnitude / maxSpeed;

        if (speedFactor > 0.05f)
        {
            // Controleert of we vooruit of achteruit rijden, zodat het sturen omdraait bij achteruitrijden
            float forwardSpeed = Vector3.Dot(rb3D.linearVelocity, transform.forward);
            float directionSign = (forwardSpeed >= 0f) ? 1f : -1f;

            // Berekent de rotatiehoek op basis van input, draaisnelheid en hoe snel de auto gaat
            float rotationAmount =
                steer *
                turnSpeed *
                speedFactor *
                directionSign *
                Time.fixedDeltaTime;

            // Roteert het model van de auto
            rb3D.MoveRotation(
                rb3D.rotation *
                Quaternion.Euler(0f, rotationAmount, 0f)
            );

            // Roteert de *bewegingsrichting* (velocity) mee, zodat de auto niet alleen draait maar ook die kant op gaat
            Vector3 rotatedVelocity =
                Quaternion.Euler(0f, rotationAmount, 0f) *
                rb3D.linearVelocity;

            float currentVelocityRotateSpeed = velocityRotateSpeed;

            // Checkt of de extra driftknop actief is, anders valt hij terug op de bounce of standaard waarde
            if (isExtraDrifting)
            {
                currentVelocityRotateSpeed = extraDriftVelocityRotateSpeed;
            }
            else if (stopMovement_Bounce != null && stopMovement_Bounce.hasCollided)
            {
                // Verlaag de grip-rotatie
                currentVelocityRotateSpeed = velocityRotateSpeed * 0.25f;
            }

            // Zorgt voor een soepele overgang tussen de oude richting en de nieuwe rijrichting
            rb3D.linearVelocity = Vector3.Lerp(
                rb3D.linearVelocity,
                rotatedVelocity,
                currentVelocityRotateSpeed * Time.fixedDeltaTime
            );
        }
    }

    // DRIFTEN (Zwaartekracht/Grip-simulatie)
    private void ApplyDrift()
    {
        // Haalt de lokale snelheid op
        Vector3 localVelocity = transform.InverseTransformDirection(rb3D.linearVelocity);

        float currentDriftFactor = driftFactor;

        if (isExtraDrifting)
        {
            currentDriftFactor = extraDriftFactor;
            playerVFX.PlayEffect(PlayerEffects.EffectType.Drift, JumpEffectPoint);
        }
        else if (stopMovement_Bounce != null && stopMovement_Bounce.hasCollided)
        {
            currentDriftFactor = bounceDriftFactor;
        }

        // Hoe lager de factor, hoe sneller de auto stopt met slippen en grip krijgt.
        localVelocity.x *= currentDriftFactor;

        // Past de aangepaste snelheid weer toe op de Rigidbody
        rb3D.linearVelocity = transform.TransformDirection(localVelocity);
    }

    // SPRINGEN
    public void OnJump(InputAction.CallbackContext context)
    {
        // checks om te voorkomen dat de spleler springt
        if (!context.performed) return;
        if (!grounded.isGrounded) return;

        // geft een directe fysieke impuls omhoog (de jump zelf)
        rb3D.AddForce(
            Vector3.up * jumpForce,
            ForceMode.Impulse
        );

        // jump VFX (expects a Transform)
        playerVFX.PlayEffect(PlayerEffects.EffectType.Jump, JumpEffectPoint);

        // jump sfx
        playerSFX.PlayJumpSound();
    }
}

using System.Collections;
using Unity.VisualScripting;
using UnityEngine;

public class Boss : EnemyBehaviorBase 
{
    KeyAndLock keyAndLock;
    new Animation animation;
    [SerializeField] private GameManager gameManager;
    public Transform XRRigCamera;
    public Transform rotatingBase;
    public Transform rotatingEye;
    private Quaternion targetBaseRotation;
    private Quaternion targetEyeRotation;
    [SerializeField] private float rotationSpeed = 2f;
    [SerializeField] private GameObject Bossdeathsphere;

    public GameObject bossEye;
    private Animation bossEyeAnimation;

    [SerializeField] private float minAttackInterval = 3f;
    [SerializeField] private float maxAttackInterval = 6f;
    [SerializeField] private GameObject laserPrefab;
    [SerializeField] private Transform laserSpawnPoint;
    [SerializeField] private ParticleSystem ParticlesSlam;
    [SerializeField] private ParticleSystem ParticlesSlam2;
    [SerializeField] private AudioSource BattleMusic;
    [SerializeField] private AudioSource Ambience;
    private EnemyHealth enemyHealth;

    private float attackTimer;
    private bool isAttacking = false;
    private bool LaserAttacking = false;
    public bool AttackingBossPossible = false;
    public bool BossStartingup = false;
    public bool BossWaveActive = false;
    public bool BossbattlestartAudio = false;
    public bool BossbattleAudioON = false;
    public bool Bossdead = false;
    private enum AttackType { Slam, Laser }

    public bool BossIsAwake;
    public bool BossIsIdle;

    protected override void Start()
    {
        animation = GetComponent<Animation>();
        bossEyeAnimation = bossEye.GetComponent<Animation>();
        enemyHealth = GetComponent<EnemyHealth>();

        BossIsAwake = false;
        BossIsIdle = false;
        BossStartingup = false;
        BossWaveActive = false;
        BossbattlestartAudio = false;        
        BossbattleAudioON = false;
        Bossdead = false;
        attackTimer = Random.Range(minAttackInterval, maxAttackInterval);
        Bossdeathsphere.SetActive(false);

        if (enemyHealth == null)
        {
            Debug.LogError("EnemyHealth component not found on Boss object.");
        }
    }

    public override void idle()
    {
        BossIsIdle = true;
    }

    public override void attack()
    {
        AttackType attackType = (Random.value < 0.5f) ? AttackType.Laser : AttackType.Slam;
        StartCoroutine(PerformAttack(attackType));
    }

    public override void wondering()
    {
        currentState= BotBase.Attack;
    }

    public override void Startup()
    {
        Debug.Log("boss startup word aangeroepen");
        if (BossStartingup)
        {
            animation.Play("Boss_WakesUp");
            StartCoroutine(WaitforStartup());
        }
    }

    public void BossAwake()
    {
        BossIsAwake = true;
        ChangeState(BotBase.Idle);
    }

    public override void DoChase()
    {
        ChangeState(BotBase.Attack);
    }

    protected override void Update()
    {
        if(BossbattlestartAudio)
        {
            if(!BossbattleAudioON)
            {
                BattleMusic.Play();
                BattleMusic.loop = true;
                BossbattleAudioON = true;
            }
        }

        if (!LaserAttacking && BossWaveActive && !Bossdead)
        {
            bossEyeAnimation.Play("BossEye_Active");
        }

        if (!BossIsIdle || Bossdead) return;

        animation.Play("Boss_Idle");

        if (XRRigCamera != null && rotatingBase != null)
        {
            Vector3 targetPosition = XRRigCamera.position;
            targetPosition.y = rotatingBase.position.y;

            Vector3 direction = targetPosition - rotatingBase.position;

            if (direction.sqrMagnitude > 0.001f)
            {
                Quaternion lookRotation = Quaternion.LookRotation(direction);
                Vector3 euler = lookRotation.eulerAngles;
                targetBaseRotation = Quaternion.Euler(-90f, euler.y + 180f, 0f);
            }

            if (!isAttacking)
            {
                rotatingBase.rotation = Quaternion.Slerp(rotatingBase.rotation, targetBaseRotation, Time.deltaTime * rotationSpeed);
            }

            if (rotatingEye != null)
            {
                Quaternion eyeLook = Quaternion.LookRotation(XRRigCamera.position - rotatingEye.position);
                targetEyeRotation = eyeLook;

                if (!isAttacking)
                {
                    rotatingEye.rotation = Quaternion.Slerp(rotatingEye.rotation, targetEyeRotation, Time.deltaTime * rotationSpeed);
                }
            }
        }

        if(BossWaveActive)
        {
            attackTimer -= Time.deltaTime;
        }

        if (attackTimer > 0f) return;

        BossIsIdle = false;
        attack();
    }

    private void FireLaser()
    {
        if (laserPrefab != null && laserSpawnPoint != null)
        {
            GameObject laserInstance = Instantiate(laserPrefab, laserSpawnPoint.position, laserSpawnPoint.rotation);
        }
    }

    public void BossDead()
    {
        Debug.Log("Boss is dead!1");

        if (!Bossdead)
        {
            Bossdeathsphere.SetActive(true);
            Debug.Log("Boss is dead!2");
            Bossdead = true;
            BossIsAwake = false;
            BossIsIdle = false;
            BossStartingup = false;
            BossbattlestartAudio = false;
            BossbattleAudioON = false;

            AudioManager.Instance.audioClips[10].Stop();
            AudioManager.Instance.audioClips[8].Stop();

            if (BattleMusic != null && BattleMusic.isPlaying)
            {
                BattleMusic.Stop();
                Ambience.Play();
            }

            bossEyeAnimation.Play("BossEye_Destruct");
            animation.Play("Boss_destruct");
            AudioManager.Instance.audioClips[11].Play();
            gameManager.Bossisdead();
            ShowObjective.instance.ShowObjectiveCanvas(7);
        }
    }

    private IEnumerator PerformAttack(AttackType attackType)
    {
        isAttacking = true;

        switch (attackType)
        {
            case AttackType.Slam:
                animation.Play("Boss_Slam");
                AudioManager.Instance.audioClips[8].Play();
                yield return new WaitForSeconds(3.5f);
                ParticlesSlam.Play();
                ParticlesSlam2.Play();
                AttackingBossPossible = true;
                yield return new WaitForSeconds(5.3f);
                break;

            case AttackType.Laser:
                if (bossEyeAnimation != null)
                {
                    bossEyeAnimation.Play("BossEye_ChargeforLaser");
                    AudioManager.Instance.audioClips[10].Play();
                    LaserAttacking = true;
                }
                yield return new WaitForSeconds(5.2f);

                FireLaser();

                break;
        }

        if(Bossdead)
        {
            BossIsIdle = false;
            BossIsAwake = false;
            BossStartingup = false;
            BossWaveActive = false;
            BossbattlestartAudio = false;
            BossbattleAudioON = false;
        }
        else
        {
            attackTimer = Random.Range(minAttackInterval, maxAttackInterval);
            isAttacking = false;
            LaserAttacking = false;
            AttackingBossPossible = false;
            BossIsIdle = true;
        }
    }

    private IEnumerator WaitforStartup()
    {
        Debug.Log("boss waitfor startup startup word aangeroepen");
        BossWaveActive = true;
        var enemies = new System.Collections.Generic.List<GameObject>();
        enemies.AddRange(GameObject.FindGameObjectsWithTag("Light"));
        enemies.AddRange(GameObject.FindGameObjectsWithTag("Medium"));
        enemies.AddRange(GameObject.FindGameObjectsWithTag("Heavy"));
        Ambience.Stop();
        foreach (GameObject enemy in enemies)
        {
            if (enemy != this.gameObject)
            {
                enemy.SetActive(false);
            }
        }
        AudioManager.Instance.audioClips[9].Play();
        yield return new WaitForSeconds(9.8f);
        BossbattlestartAudio = true;
        idle();
    }
}

using UnityEngine;

public class RokokoAbsoluteRootLock : MonoBehaviour
{
    [Header("Root Lock Settings")]
    [SerializeField] private bool lockRotation = true;

    private Vector3 lockedPosition;
    private Quaternion lockedRotation;

    void Start()
    {
        // Capture the position & rotation of the rig at calibration time
        lockedPosition = transform.position;
        lockedRotation = transform.rotation;
    }

    void LateUpdate()
    {
        // FORCE the rig to stay at the calibration spot
        transform.position = lockedPosition;

        // freeze world rotation so Rokoko cannot rotate the root
        if (lockRotation)
            transform.rotation = lockedRotation;
    }

    // Call this manually after calibration if needed
    public void RecalibrateRoot()
    {
        lockedPosition = transform.position;
        lockedRotation = transform.rotation;
    }
}

#include <LiquidCrystal.h>

// ===== LCD pins (alleen 8–13 gebruikt) =====
LiquidCrystal lcd(13,12,11,10,9,8);

// ===== Inputs =====
const int buttonPin = A1;
const int potPin = A3;

// ===== Outputs =====
const int greenLedBPin = 5;
const int redLedBPin  = 6;
const int buzzerPin  = 7;

// RGB LEDs
const int BluePin = 2;
const int GreenPin = 3;
const int RedPin = 4;

// Button state
bool lastButtonState = HIGH;
bool buttonPressed = false;

// LED states
bool blinkBlue = false;
bool blinkRed  = false;
bool GreenOn = false;

bool buttonLEDg = false;
bool buttonLEDr = false;

bool ledState  = false;
unsigned long lastBlinkTime = 0;

unsigned long lastDebounceTime = 0;
const unsigned long debounceDelay = 50;
bool lastReading = HIGH;
bool buttonState = HIGH;

void setup()
{
  pinMode(buttonPin, INPUT_PULLUP);
  pinMode(greenLedBPin, OUTPUT);
  pinMode(redLedBPin, OUTPUT);
  pinMode(buzzerPin, OUTPUT);
  pinMode(RedPin, OUTPUT);
  pinMode(BluePin, OUTPUT);
  pinMode(GreenPin, OUTPUT);

  lcd.begin(20,4);

  Serial.begin(9600);
}

void loop()
{
  // ======================
  // Input → Unity
  // ======================
  bool currentState = digitalRead(buttonPin);

  //button state
  bool reading = digitalRead(buttonPin);

  if (reading != lastReading)
  {
    lastDebounceTime = millis();
  }

  if ((millis() - lastDebounceTime) > debounceDelay)
  {
    if (reading != buttonState)
    {
      buttonState = reading;

      if (buttonState == LOW)
      {
        buttonPressed = !buttonPressed;
      }
    }
  }

  lastReading = reading;

  int potValue = analogRead(potPin);

  Serial.print(buttonPressed ? 1 : 0);
  Serial.print(",");
  Serial.println(potValue);

  // ======================
  // Unity → Output
  // ======================
  if (Serial.available())
  {
    String cmd = Serial.readStringUntil('\n');
    cmd.trim();

    if (cmd == "BLINK_BLUE") blinkBlue = true;
    if (cmd == "STOP_BLUE")  blinkBlue = false;

    if (cmd == "BLINK_RED")  blinkRed = true;
    if (cmd == "STOP_RED")   blinkRed = false;

    if (cmd == "GREEN_ON")   GreenOn = true;
    if (cmd == "GREEN_OFF")  GreenOn = false;

    if (cmd == "BUTTON_RED_ON") buttonLEDr = true;
    if (cmd == "BUTTON_RED_OFF") buttonLEDr = false;

    if (cmd == "BUTTON_GREEN_ON") buttonLEDg = true;
    if (cmd == "BUTTON_GREEN_OFF") buttonLEDg = false;

    if (cmd == "ALL_OFF")
    {
      blinkBlue = false;
      blinkRed = false;
      GreenOn = false;
      buttonLEDg = false;
      buttonLEDr = false;

      // Immediately force outputs off
      digitalWrite(BluePin, LOW);
      digitalWrite(RedPin, LOW);
      digitalWrite(GreenPin, LOW);
      digitalWrite(greenLedBPin, LOW);
      digitalWrite(redLedBPin, LOW);
      noTone(buzzerPin);
    }
  }

  // ======================
  // Button LEDs
  // ======================
  if (buttonLEDg)
  {
    digitalWrite(greenLedBPin, HIGH);
    digitalWrite(redLedBPin, LOW);
  }
  else if (buttonLEDr)
  {
    digitalWrite(redLedBPin, HIGH);
    digitalWrite(greenLedBPin, LOW);
  }
  else
  {
    digitalWrite(greenLedBPin, LOW);
    digitalWrite(redLedBPin, LOW);
  }

  // ======================
  // Blink logic
  // ======================
  if (millis() - lastBlinkTime > 300)
  {
    lastBlinkTime = millis();
    ledState = !ledState;

    digitalWrite(BluePin,  blinkBlue ? ledState : LOW);
    digitalWrite(RedPin,   blinkRed  ? ledState : LOW);
    digitalWrite(GreenPin, GreenOn && !blinkBlue && !blinkRed ? HIGH : LOW);

    // buzzer sync
    if (blinkBlue || blinkRed)
    {
      if (ledState) tone(buzzerPin,1000);
      else noTone(buzzerPin);
    }
    else
      noTone(buzzerPin);

    // LCD Status
    lcd.clear();

    lcd.setCursor(0,0);
    lcd.print("CORE STATUS:");

    if (blinkRed) 
    {
      lcd.setCursor(4,1);
      lcd.print("!!!ERROR!!!");
      lcd.setCursor(2,3);
      lcd.print("CORE OVERHEATED!");
    }
    else if (blinkBlue)
    {
      lcd.setCursor(4,1);
      lcd.print("!!!ERROR!!!");
      lcd.setCursor(1,3);
      lcd.print("CORE UNDERCOOLED!");
    }
    else if (GreenOn)
    {
      lcd.setCursor(7,2);
      lcd.print("Stable");
    }
    else
    {
      lcd.setCursor(7,2);
      lcd.print("Stable");
    }
  }

  delay(10);
}

void Update()
{
    if (Input.GetKey(KeyCode.W))
        rb.AddForce(transform.up * thrust);

    float rotate = Input.GetAxis("Horizontal");
    rb.MoveRotation(rb.rotation - rotate * rotateSpeed * Time.deltaTime);
}

void SpawnAsteroid()
{
    Vector3 pos = Random.onUnitSphere * spawnRadius;
    float size = Random.Range(0.5f, 2.5f);

    GameObject ast = Instantiate(asteroidPrefab, pos, Random.rotation);
    ast.transform.localScale = Vector3.one * size;

    Rigidbody rb = ast.GetComponent<Rigidbody>();
    rb.AddForce(Random.onUnitSphere * Random.Range(5,15), ForceMode.Impulse);
}

public class StepGuide : MonoBehaviour
{
    public List<TrainingStep> steps;
    private int currentStep = 0;

    void CheckStepCompletion()
    {
        if (steps[currentStep].IsCompleted())
        {
            currentStep++;
            ShowNextInstruction();
        }
    }
}

bool ValidateHandPose(HandPose required)
{
    float similarity = Vector3.Dot(
        currentPose.palmNormal,
        required.palmNormal
    );

    return similarity > 0.95f;
}

void OnTrackedImagesChanged(ARTrackedImagesChangedEventArgs args)
{
    foreach (var trackedImage in args.added)
    {
        string artworkId = trackedImage.referenceImage.name;
        SpawnARContent(artworkId, trackedImage.transform);
    }
}

void HandleTouchInput()
{
    if (Input.touchCount == 2)
    {
        Touch t1 = Input.GetTouch(0);
        Touch t2 = Input.GetTouch(1);

        float pinchDist = Vector2.Distance(t1.position, t2.position);
        float scale = pinchDist / initialPinchDist;

        model.localScale = initialScale * scale;
    }
}
